public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    if (n == 0) {
        return 0;
    }

    int maxArea = 0;
    int i = 0;
    while (i < n) {
        int minHeight = Integer.MAX_VALUE;
        int j = i;
        while (j < n) {
            minHeight = Math.min(minHeight, heights[j]);
            j++;
        }

        maxArea = Math.max(maxArea, minHeight * (j - i));
        i++;
    }

    return maxArea;
}

