public static boolean isBoomerang(int[][] points) {
    // Check if the array contains exactly three points
    if (points.length != 3) {
        return false;
    }

    // Check if the points are not collinear
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) {
        return false;
    }

    // Check if the points are not identical.
    if (x1 == x2 && y1 == y2 && x2 == x3 && y2 == y3) {
        return false;
    }

    // Return true if all the above conditions are met.
    return true;
}

